//! AST → Go source.
//!
//! One pass over the checked AST. Every expression's Go type comes from
//! the type inty recorded for it during inference (keyed by span), so
//! the emitter never guesses: `a + b` becomes float64 addition or string
//! concatenation depending on what inty proved about `a` and `b`.
//!
//! Layout of the generated file:
//!
//! ```text
//! package main / imports
//! struct declarations      (one per object shape)
//! package-level vars       (top-level `var` / `let` / `const`)
//! top-level functions      (top-level `function` declarations)
//! func main()              (every other top-level statement, in order)
//! runtime helpers          (runtime.go)
//! ```

use std::collections::HashMap;

use inty::ast::free_idents::free_identifiers_in_stmt;
use inty::ast::*;
use inty::infer::InferState;
use inty::span::Span;
use inty::types::Type;

use crate::types::{GoType, TypeMapper};
use crate::{unsupported, Result};

const RUNTIME: &str = include_str!("runtime.go");

/// Emit a whole program. `state` must be the state that checked
/// `program`, with `expr_types` recording enabled.
pub fn emit_program(program: &Program, state: &mut InferState) -> Result<String> {
    let types = state
        .expr_types
        .take()
        .expect("inty-go: expression-type recording must be enabled before inference");
    let mut e = Emitter {
        state,
        types,
        tm: TypeMapper::default(),
        buf: String::new(),
        indent: 0,
        ret_stack: Vec::new(),
        tmp: 0,
        scopes: vec![HashMap::new()],
    };

    let mut globals = String::new();
    let mut funcs = String::new();
    let mut main_body = String::new();

    // Bind every top-level name first: function bodies may refer to
    // functions and variables declared further down (hoisting).
    for stmt in &program.statements {
        match stmt {
            Stmt::FunctionDecl { name, span, .. } => {
                let t = e.fn_type(*span)?;
                e.bind(name, t);
            }
            Stmt::Var { declarations, .. } => {
                for d in declarations {
                    let t = e.decl_type(d)?;
                    e.bind(&d.name, t);
                }
            }
            _ => {}
        }
    }

    // Pass 1: top-level functions become Go functions; top-level
    // variables become package-level vars so functions can see them.
    for stmt in &program.statements {
        match stmt {
            Stmt::FunctionDecl {
                name,
                params,
                body,
                span,
                ..
            } => {
                e.buf.clear();
                e.indent = 0;
                let (sig_params, ptys, ret) = e.signature(params, *span)?;
                e.line(&format!(
                    "func {}({}){} {{",
                    mangle(name),
                    sig_params,
                    e.tm.render_result(&ret)
                ));
                e.indent += 1;
                e.function_body(params, &ptys, body, &ret)?;
                e.indent -= 1;
                e.line("}");
                funcs.push_str(&e.buf);
                funcs.push('\n');
            }
            Stmt::Var { declarations, .. } => {
                for d in declarations {
                    let ty = e.decl_type(d)?;
                    globals.push_str(&format!("var {} {}\n", mangle(&d.name), e.tm.render(&ty)));
                }
            }
            _ => {}
        }
    }

    // Pass 2: everything else runs in `main`, in source order.
    e.buf.clear();
    e.indent = 1;
    e.ret_stack.push(GoType::Unit);
    for stmt in &program.statements {
        match stmt {
            Stmt::FunctionDecl { .. } => {}
            Stmt::Var { declarations, .. } => {
                for d in declarations {
                    if let Some(init) = &d.init {
                        let ty = e.decl_type(d)?;
                        let v = e.expr_as(init, &ty)?;
                        e.line(&format!("{} = {}", mangle(&d.name), v));
                    }
                }
            }
            other => e.stmt(other, &[])?,
        }
    }
    e.ret_stack.pop();
    main_body.push_str(&e.buf);

    let mut out = String::new();
    out.push_str("// Code generated by `inty go` from type-checked JavaScript. DO NOT EDIT.\n");
    out.push_str("// Requires Go >= 1.22 (per-iteration loop variables, like JS `let`).\n\n");
    out.push_str("package main\n\n");
    out.push_str(
        "import (\n\t\"bufio\"\n\t\"math\"\n\t\"math/bits\"\n\t\"math/rand\"\n\t\"os\"\n\t\"strconv\"\n\t\"strings\"\n\t\"time\"\n)\n\n",
    );
    out.push_str(&e.tm.render_structs());
    if !globals.is_empty() {
        out.push_str(&globals);
        out.push('\n');
    }
    out.push_str(&funcs);
    out.push_str("func main() {\n\tdefer intyOut.Flush()\n");
    out.push_str(&main_body);
    out.push_str("}\n\n");
    out.push_str(RUNTIME);
    Ok(out)
}

struct Emitter<'a> {
    state: &'a mut InferState,
    types: HashMap<(usize, usize), Type>,
    tm: TypeMapper,
    /// Statement output for the function currently being emitted.
    buf: String,
    indent: usize,
    /// Result type of each enclosing function (innermost last).
    ret_stack: Vec<GoType>,
    /// Counter for fresh temporaries.
    tmp: usize,
    /// Declared Go type of every JS binding in scope, innermost last.
    /// An identifier's type comes from here rather than from the type
    /// recorded at the use site: a use inside a hoisted function can be
    /// recorded as a structural *view* of the binding (e.g. an array seen
    /// as `{length: Number | ρ}`), which isn't the variable's Go type.
    scopes: Vec<HashMap<String, GoType>>,
}

/// A number the emitter can fold at translation time. Folding happens
/// in f64, matching JavaScript; Go would evaluate constant expressions
/// exactly (`0.1 + 0.2` is precisely `0.3` as a Go constant).
fn const_num(e: &Expr) -> Option<f64> {
    match e {
        Expr::Lit {
            value: Literal::Number(n),
            ..
        } => Some(*n),
        Expr::Unary {
            op: UnaryOp::Neg,
            argument,
            ..
        } => const_num(argument).map(|n| -n),
        Expr::Unary {
            op: UnaryOp::Pos,
            argument,
            ..
        } => const_num(argument),
        Expr::Binary {
            op, left, right, ..
        } => {
            let (a, b) = (const_num(left)?, const_num(right)?);
            Some(match op {
                BinOp::Add => a + b,
                BinOp::Sub => a - b,
                BinOp::Mul => a * b,
                BinOp::Div => a / b,
                BinOp::Mod => a % b,
                BinOp::Pow => a.powf(b),
                _ => return None,
            })
        }
        Expr::Member {
            object, property, ..
        } => match (&**object, property.as_str()) {
            (Expr::Ident { name, .. }, p) if name == "Math" => math_constant(p),
            (Expr::Ident { name, .. }, p) if name == "Number" => match p {
                "MAX_SAFE_INTEGER" => Some(9007199254740991.0),
                "MIN_SAFE_INTEGER" => Some(-9007199254740991.0),
                "EPSILON" => Some(f64::EPSILON),
                "MAX_VALUE" => Some(f64::MAX),
                "MIN_VALUE" => Some(5e-324),
                _ => None,
            },
            _ => None,
        },
        _ => None,
    }
}

fn math_constant(name: &str) -> Option<f64> {
    use std::f64::consts;
    Some(match name {
        "PI" => consts::PI,
        "E" => consts::E,
        "LN2" => consts::LN_2,
        "LN10" => consts::LN_10,
        "LOG2E" => consts::LOG2_E,
        "LOG10E" => consts::LOG10_E,
        "SQRT2" => consts::SQRT_2,
        _ => return None,
    })
}

/// Go spelling of a float64 value. Always carries a `.` or exponent so
/// the untyped constant defaults to float64, never int.
fn num_lit(n: f64) -> String {
    if n.is_nan() {
        "math.NaN()".into()
    } else if n.is_infinite() {
        if n > 0.0 {
            "math.Inf(1)"
        } else {
            "math.Inf(-1)"
        }
        .into()
    } else if n == 0.0 && n.is_sign_negative() {
        "math.Copysign(0, -1)".into()
    } else {
        // `{:?}` is the shortest round-trip form: `3.0`, `0.1`, `1e21`.
        let s = format!("{:?}", n);
        if n < 0.0 {
            format!("({})", s)
        } else {
            s
        }
    }
}

fn go_string_lit(s: &str) -> String {
    let mut out = String::from("\"");
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if (c as u32) < 0x20 || c as u32 == 0x7f => {
                out.push_str(&format!("\\x{:02x}", c as u32))
            }
            c => out.push(c),
        }
    }
    out.push('"');
    out
}

